// Subscribe once, for example in the form constructor:
timer1.Tick += timer1_Tick;
timer1.Interval = 1000; // milliseconds
timer1.Start();

private void timer1_Tick(object sender, EventArgs e)
{
    lblClock.Text = DateTime.Now.ToLongTimeString();
}

// Subscribe once, for example in the form constructor:
backgroundWorker1.DoWork += backgroundWorker1_DoWork;
backgroundWorker1.WorkerReportsProgress = true;
backgroundWorker1.WorkerSupportsCancellation = true;
backgroundWorker1.RunWorkerAsync();

private void backgroundWorker1_DoWork(object sender, DoWorkEventArgs e)
{
    var worker = (BackgroundWorker)sender;
    for (int i = 1; i <= 100; i++)
    {
        if (worker.CancellationPending)
        {
            e.Cancel = true;
            return;
        }
        System.Threading.Thread.Sleep(50); // simulate work
        worker.ReportProgress(i);
    }
    e.Result = "Finished";
}

// Subscribe once, for example in the form constructor:
backgroundWorker1.ProgressChanged += backgroundWorker1_ProgressChanged;

private void backgroundWorker1_ProgressChanged(object sender, ProgressChangedEventArgs e)
{
    prgWork.Value = e.ProgressPercentage;
    lblStatus.Text = e.ProgressPercentage + "%";
}

// Subscribe once, for example in the form constructor:
backgroundWorker1.RunWorkerCompleted += backgroundWorker1_RunWorkerCompleted;

private void backgroundWorker1_RunWorkerCompleted(object sender, RunWorkerCompletedEventArgs e)
{
    if (e.Error != null)
    {
        MessageBox.Show("Failed: " + e.Error.Message);
    }
    else if (e.Cancelled)
    {
        lblStatus.Text = "Cancelled";
    }
    else
    {
        lblStatus.Text = (string)e.Result;
    }
}

// Subscribe once, for example in the form constructor:
notifyIcon1.MouseClick += notifyIcon1_MouseClick;

private void notifyIcon1_MouseClick(object sender, MouseEventArgs e)
{
    if (e.Button == MouseButtons.Left)
    {
        Show();
        WindowState = FormWindowState.Normal;
        Activate();
    }
}

